#define _CRT_SECURE_NO_WARNINGS
#include "aervault_journal.h"
#include "aervault_budget.h"
#include "aervault_diag.h"
#include "aervault_queue.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MEDIA_MAX 32768u
static unsigned g_seed,g_point,g_mode,g_scenario;
static unsigned g_combinations[8];
#define CHECK(x) do { if(!(x)){FILE *ff;fprintf(stderr,"FAIL scenario=%u seed=%u point=%u mode=%u line=%d: %s\n",g_scenario,g_seed,g_point,g_mode,__LINE__,#x);ff=fopen("aervault-campaign-failure.json","w");if(ff){fprintf(ff,"{\"scenario\":%u,\"seed\":%u,\"point\":%u,\"mode\":%u,\"line\":%d,\"repro\":\"aervault_campaign --repro %u %u %u %u\"}\n",g_scenario,g_seed,g_point,g_mode,__LINE__,g_scenario,g_seed,g_point,g_mode);fclose(ff);}return 1;} } while(0)

typedef struct { uint8_t durable[MEDIA_MAX], live[MEDIA_MAX]; size_t size; unsigned op, fail_at, mode; unsigned programs, erases, syncs; } medium;
static int trip(medium *m) { unsigned n=++m->op; return m->fail_at==n; }
static int rd(void *c,uint32_t o,void *p,size_t n){medium*m=c;if((uint64_t)o+n>m->size)return -1;memcpy(p,m->live+o,n);return 0;}
static int pg(void*c,uint32_t o,const void*p,size_t n){medium*m=c;const uint8_t*b=p;size_t i,lim=n;int fail=trip(m);m->programs++;if((uint64_t)o+n>m->size)return -1;if(fail&&m->mode==1)lim=n/2u;else if(fail&&m->mode==2)lim=0;for(i=0;i<lim;i++){if((m->live[o+i]&b[i])!=b[i])return -1;m->live[o+i]&=b[i];}if(fail&&(m->mode==1||m->mode==3))memcpy(m->durable+o,m->live+o,lim);return fail?-77:0;}
static int er(void*c,uint32_t o,size_t n){medium*m=c;int fail=trip(m);m->erases++;if((uint64_t)o+n>m->size)return -1;if(fail&&m->mode==1)n/=2u;else if(fail&&m->mode==2)n=0;memset(m->live+o,0xff,n);if(fail&&(m->mode==1||m->mode==3))memcpy(m->durable+o,m->live+o,n);return fail?-78:0;}
static int sy(void*c){medium*m=c;int fail=trip(m);size_t n=m->size;m->syncs++;if(fail&&m->mode==1)n/=2u;else if(fail&&m->mode==2)n=0;memcpy(m->durable,m->live,n);return fail?-79:0;}
static void crash(medium*m){memcpy(m->live,m->durable,m->size);m->op=0;m->fail_at=0;}
static uint32_t rng(uint32_t*x){*x^=*x<<13;*x^=*x>>17;*x^=*x<<5;return *x;}
static int visit(void*c,const av_journal_record*r,const uint8_t*p){unsigned*v=c;if(r->type==1&&r->length==4&&memcmp(p,"BASE",4)==0)(*v)|=1u;if(r->type==1&&r->length==4&&memcmp(p,"NEXT",4)==0)(*v)|=2u;return 0;}
static av_journal_status mount(av_journal*j,medium*m,av_journal_io*io,av_journal_layout*l,uint8_t*w){io->ctx=m;io->read=rd;io->program=pg;io->erase=er;io->sync=sy;l->bank_offset[0]=0;l->bank_offset[1]=m->size/2;l->bank_size=(uint32_t)m->size/2;l->erase_size=256;l->program_size=4;l->erased_value=255;return av_journal_mount(j,io,l,w,1024);}
static int keep_one(void*c,const av_journal_record*r,const uint8_t*p){(void)c;(void)r;(void)p;return 1;}
static int fault_case(unsigned seed,unsigned point,unsigned mode){medium m;av_journal j,j2;av_journal_io io;av_journal_layout l;uint8_t w[1024];unsigned bits=0;av_journal_status s;g_scenario=1;g_seed=seed;g_point=point;g_mode=mode;memset(&m,255,sizeof m);m.size=8192;m.op=0;m.fail_at=0;m.mode=0;m.programs=m.erases=m.syncs=0;CHECK(av_journal_format(&j,&(av_journal_io){&m,rd,pg,er,sy},&(av_journal_layout){{0,4096},4096,256,4,255},w,sizeof w)==AV_JOURNAL_OK);CHECK(av_journal_append(&j,1,"BASE",4,NULL)==AV_JOURNAL_OK);memcpy(m.durable,m.live,m.size);m.op=0;m.fail_at=point;m.mode=mode;s=av_journal_append(&j,1,"NEXT",4,NULL);(void)s;crash(&m);memset(w,0,sizeof w);s=mount(&j2,&m,&io,&l,w);if(s==AV_JOURNAL_OK||s==AV_JOURNAL_TORN){av_journal_status scan=av_journal_scan(&j2,visit,&bits);CHECK(scan==AV_JOURNAL_OK||scan==AV_JOURNAL_TORN);CHECK((bits&1u)!=0);CHECK(bits==1u||bits==3u);}else CHECK(s==AV_JOURNAL_CORRUPT||s==AV_JOURNAL_IO);return 0;}
static int format_fault(unsigned point,unsigned mode){medium m;av_journal j,j2;av_journal_io io={&m,rd,pg,er,sy};av_journal_layout l={{0,4096},4096,256,4,255};uint8_t w[1024];av_journal_status s;g_scenario=2;g_seed=0xF04A7u;g_point=point;g_mode=mode;memset(&m,255,sizeof m);m.size=8192;m.op=0;m.fail_at=point;m.mode=mode;(void)av_journal_format(&j,&io,&l,w,sizeof w);crash(&m);memset(w,0,sizeof w);s=av_journal_mount(&j2,&io,&l,w,sizeof w);CHECK(s==AV_JOURNAL_CORRUPT||s==AV_JOURNAL_OK);return 0;}
static int random_case(uint32_t seed){medium m;av_journal j,j2;av_journal_io io;av_journal_layout l;uint8_t w[1024];unsigned i,bits=0;uint32_t x=seed;size_t banksize;av_journal_status s;static const uint32_t erases[]={128u,256u,512u},programs[]={4u,8u,16u};g_scenario=4;g_seed=seed;g_point=g_mode=0;memset(&m,255,sizeof m);m.size=MEDIA_MAX;{uint32_t e=erases[rng(&x)%3u];banksize=(size_t)e*(8u+rng(&x)%24u);l.erase_size=e;l.program_size=programs[rng(&x)%3u];}if(2*banksize>m.size)banksize=m.size/2u;m.op=0;m.fail_at=0;m.mode=0;io.ctx=&m;io.read=rd;io.program=pg;io.erase=er;io.sync=sy;l.bank_offset[0]=0;l.bank_offset[1]=(uint32_t)banksize;l.bank_size=(uint32_t)banksize;l.erased_value=255;CHECK(av_journal_format(&j,&io,&l,w,sizeof w)==AV_JOURNAL_OK);
 {uint32_t modules=rng(&x)&7u;av_queue q;av_queue_item qi[4];av_diag d;av_diag_record dr;av_budget b;g_combinations[modules]++;if(modules&1u){uint64_t id0,id1;CHECK(av_queue_open(&q,&j,qi,4)==AV_JOURNAL_OK);CHECK(av_queue_push(&q,"q0",2,&id0)==AV_JOURNAL_OK);CHECK(av_queue_push(&q,"q1",2,&id1)==AV_JOURNAL_OK&&id1>id0);CHECK(av_queue_ack(&q,id0)==AV_JOURNAL_OK);}if(modules&2u){memset(&dr,0,sizeof dr);dr.timestamp=seed;dr.event=seed|1u;dr.severity=1;dr.length=2;dr.payload[0]=(uint8_t)seed;dr.payload[1]=(uint8_t)(seed>>8);CHECK(av_diag_init(&d,&j,4)==AV_JOURNAL_OK);CHECK(av_diag_write(&d,&dr,NULL)==AV_JOURNAL_OK);}if(modules&4u){av_budget_init(&b,32,8,0,0);CHECK(av_budget_check(&b,1,1)==AV_BUDGET_ALLOW);CHECK(av_budget_charge(&b,1,1)==AV_BUDGET_ALLOW);}}
 for(i=0;i<1+(rng(&x)%12u);i++){uint8_t v[4]={(uint8_t)seed,(uint8_t)i,(uint8_t)(seed>>8),0x5a};av_journal_status a=av_journal_append(&j,1,v,sizeof v,NULL);if(a==AV_JOURNAL_FULL)break;CHECK(a==AV_JOURNAL_OK);if((rng(&x)&7u)==0u){memcpy(m.durable,m.live,m.size);}}
 /* A fresh mount must never invent a committed record. */
 memcpy(m.durable,m.live,m.size);crash(&m);memset(w,0,sizeof w);s=av_journal_mount(&j2,&io,&l,w,sizeof w);CHECK(s==AV_JOURNAL_OK||s==AV_JOURNAL_TORN);(void)bits;return 0;}
static int compact_fault(unsigned point,unsigned mode){medium m;av_journal j,j2;av_journal_io io={&m,rd,pg,er,sy};av_journal_layout l={{0,4096},4096,256,4,255};uint8_t w[1024];av_journal_status s;unsigned bits=0;g_scenario=3;g_seed=0xC04FAC7u;g_point=point;g_mode=mode;memset(&m,255,sizeof m);m.size=8192;m.op=0;m.fail_at=0;m.mode=0;CHECK(av_journal_format(&j,&io,&l,w,sizeof w)==AV_JOURNAL_OK);CHECK(av_journal_append(&j,1,"BASE",4,NULL)==AV_JOURNAL_OK);memcpy(m.durable,m.live,m.size);m.op=0;m.fail_at=point;m.mode=mode;(void)av_journal_compact(&j,keep_one,NULL);crash(&m);memset(w,0,sizeof w);s=av_journal_mount(&j2,&io,&l,w,sizeof w);CHECK(s==AV_JOURNAL_OK);CHECK(av_journal_scan(&j2,visit,&bits)==AV_JOURNAL_OK);CHECK(bits==1u);return 0;}
int main(int argc,char**argv){unsigned runs=10000u,i,points=0,compact_points=0,format_points=0;FILE*f;const char*report=argc>2?argv[2]:"aervault-campaign-results.json";if(argc>=6&&strcmp(argv[1],"--repro")==0){unsigned sc=(unsigned)strtoul(argv[2],NULL,10),sd=(unsigned)strtoul(argv[3],NULL,10),pt=(unsigned)strtoul(argv[4],NULL,10),md=(unsigned)strtoul(argv[5],NULL,10);if(sc==1)return fault_case(sd,pt,md);if(sc==2)return format_fault(pt,md);if(sc==3)return compact_fault(pt,md);if(sc==4)return random_case(sd);return 2;}if(argc>1)runs=(unsigned)strtoul(argv[1],NULL,10);if(runs<10000u)runs=10000u;
 /* Probe reachable append operation count; exercise every call boundary and
    before/partial/after durable behaviors. */
 {medium m;av_journal j;av_journal_io io={&m,rd,pg,er,sy};av_journal_layout l={{0,4096},4096,256,4,255};uint8_t w[1024];memset(&m,255,sizeof m);m.size=8192;m.mode=0;m.fail_at=0;m.op=0;CHECK(av_journal_format(&j,&io,&l,w,sizeof w)==AV_JOURNAL_OK);CHECK(av_journal_append(&j,1,"BASE",4,NULL)==AV_JOURNAL_OK);m.op=0;CHECK(av_journal_append(&j,1,"NEXT",4,NULL)==AV_JOURNAL_OK);points=m.op;}
 for(i=1;i<=points;i++)for(unsigned mode=0;mode<4;mode++)if(fault_case(0xA001u+i,i,mode))return 1;
 {medium m;av_journal j;av_journal_io io={&m,rd,pg,er,sy};av_journal_layout l={{0,4096},4096,256,4,255};uint8_t w[1024];memset(&m,255,sizeof m);m.size=8192;m.op=0;m.fail_at=0;m.mode=0;CHECK(av_journal_format(&j,&io,&l,w,sizeof w)==AV_JOURNAL_OK);format_points=m.op;}
 for(i=1;i<=format_points;i++)for(unsigned mode=0;mode<4;mode++)if(format_fault(i,mode))return 1;
 {medium m;av_journal j;av_journal_io io={&m,rd,pg,er,sy};av_journal_layout l={{0,4096},4096,256,4,255};uint8_t w[1024];memset(&m,255,sizeof m);m.size=8192;m.op=0;m.fail_at=0;m.mode=0;CHECK(av_journal_format(&j,&io,&l,w,sizeof w)==AV_JOURNAL_OK);CHECK(av_journal_append(&j,1,"BASE",4,NULL)==AV_JOURNAL_OK);m.op=0;CHECK(av_journal_compact(&j,keep_one,NULL)==AV_JOURNAL_OK);compact_points=m.op;}
 for(i=1;i<=compact_points;i++)for(unsigned mode=0;mode<4;mode++)if(compact_fault(i,mode))return 1;
 for(i=0;i<runs;i++){uint32_t seed=0x9e3779b9u^(i*0x85ebca6bu);if(random_case(seed))return 1;}
 f=fopen(report,"w");if(!f){perror("campaign report");return 2;}fprintf(f,"{\n  \"status\": \"PASS\",\n  \"seed_start\": 2654435769,\n  \"random_runs\": %u,\n  \"format_operation_points\": %u,\n  \"append_operation_points\": %u,\n  \"compaction_operation_points\": %u,\n  \"fault_cases\": %u,\n  \"module_combinations_queue_diag_budget\": [%u,%u,%u,%u,%u,%u,%u,%u],\n  \"models\": [\"pre-operation failure\", \"partial operation\", \"error after durable operation\"],\n  \"note\": \"host test; no hardware or physical power-cut validation\"\n}\n",runs,format_points,points,compact_points,(format_points+points+compact_points)*4u,g_combinations[0],g_combinations[1],g_combinations[2],g_combinations[3],g_combinations[4],g_combinations[5],g_combinations[6],g_combinations[7]);fclose(f);printf("campaign PASS random=%u format_points=%u append_points=%u compact_points=%u fault_cases=%u report=%s\n",runs,format_points,points,compact_points,(format_points+points+compact_points)*4u,report);return 0;}
